SELECT 
FROM risk_clue_report

    del_flag = '0'

        AND (clue_no LIKE CONCAT('%', #{keyword}, '%')
          OR clue_title LIKE CONCAT('%', #{keyword}, '%')
          OR risk_subject LIKE CONCAT('%', #{keyword}, '%'))

    AND report_time >= #{reportTimeStart}
    AND report_time <= #{reportTimeEnd}
    AND clue_type = #{clueType}
    AND review_status = #{reviewStatus}
    AND transfer_status = #{transferStatus}
    AND feedback_status = #{feedbackStatus}
    AND risk_level = #{riskLevel}
    AND street_code = #{streetCode}
    AND street_name = #{streetName}

ORDER BY COALESCE(report_time, create_time) DESC, id DESC
